import { Node } from 'cc';
import { ChildPanelBase } from '../../core/ChildPanelBase';
import { DetailSubWindow } from '../../core/DetailSubWindow';
import { ds3Label, ds3Node, ds3Reflow, ds3SetActive } from './Ds3NodeLookup';
import { UCUFLogger, LogCategory } from '../../../core/utils/UCUFLogger';
import type { GeneralConfig } from '../../../core/models/GeneralUnit';
import {
    buildSkillDetailView,
    formatSkillDetailText,
    type SkillDetailSource,
    type SkillDetailState,
} from '../../../core/systems/SkillDetailView';
import { getTacticTpCost } from '../../../core/systems/SortieDeploy';
import { resolveBattleSkillProfile } from '../../../battle/skills/BattleSkillProfiles';
import type { CanonicalTacticDefinition, CanonicalUltimateDefinition } from '../../../shared/SkillRuntimeContract';
import { loadTacticDefinitionMap, loadUltimateDefinitionMap } from '../general-detail/SkillDefinitionCache';
import { formatTacticCategory } from '../general-detail/GeneralDetailFormatters';

export interface Ds3TacticRow {
    glyph: string;
    name: string;
}

export interface Ds3LockedTacticRow extends Ds3TacticRow {
    hint: string;
}

export interface Ds3TacticRows {
    /** 第一筆是主戰法，其餘是已習得列 */
    learned: Ds3TacticRow[];
    inspired: Ds3LockedTacticRow[];
    locked: Ds3LockedTacticRow[];
}

/** 片段槽位數：主戰法 1＋已習得 3、可習得 2、無法習得 2 */
const LEARNED_SLOT_COUNT = 4;
const INSPIRED_SLOT_COUNT = 2;
const LOCKED_SLOT_COUNT = 2;
const LOCK_PREFIX = /^🔒\s*/u;

/** 武將資料只有戰法名稱，標籤、TP、說明、等級都是設計稿範例，先不顯示 */
const TACTIC_DEMO_NODES = [
    'TacticMain_tag0', 'TacticMain_tag1', 'TacticMain_tag2', 'TacticMain_desc', 'TacticMain_level',
    'TacticLearned1_tag0', 'TacticLearned1_desc', 'TacticLearned1_level',
    'TacticLearned2_tag0', 'TacticLearned2_tag1', 'TacticLearned2_tag2', 'TacticLearned2_desc', 'TacticLearned2_level',
    'TacticLearned3_tag0', 'TacticLearned3_tag1', 'TacticLearned3_tag2', 'TacticLearned3_desc', 'TacticLearned3_level',
    'TacticInspired1_badge', 'TacticInspired1_tag0', 'TacticInspired1_tag1', 'TacticInspired1_hint',
    'TacticInspired2_badge', 'TacticInspired2_tag0', 'TacticInspired2_tag1', 'TacticInspired2_hint',
];

function glyphOf(name: string): string {
    return [...name][0] ?? '';
}

/** 把武將戰法資料轉成技分頁列；列數受片段槽位上限限制。 */
export function buildDs3TacticRows(cfg: Partial<GeneralConfig> | null | undefined): Ds3TacticRows {
    const clean = (list: unknown): string[] => (Array.isArray(list) ? list : [])
        .filter((v): v is string => typeof v === 'string')
        .map((v) => v.replace(LOCK_PREFIX, '').trim())
        .filter((v) => v.length > 0);

    const learned = clean(cfg?.learnedTactics).slice(0, LEARNED_SLOT_COUNT)
        .map((name) => ({ glyph: glyphOf(name), name }));
    const inspired = clean(cfg?.inspiredTactics).slice(0, INSPIRED_SLOT_COUNT)
        .map((name) => ({ glyph: glyphOf(name), name, hint: '未啟發' }));
    const locked = clean(cfg?.lockedTactics).slice(0, LOCKED_SLOT_COUNT)
        .map((name) => ({ glyph: glyphOf(name), name, hint: '🔒 待解鎖' }));
    return { learned, inspired, locked };
}

/** 可點詳情的列：槽位鍵 → 點擊節點名（主戰法點名稱標籤，其餘點整列） */
const DETAIL_SLOT_NODES: ReadonlyArray<{ key: string; node: string }> = [
    { key: 'main', node: 'TacticMain_name' },
    { key: 'TacticLearned1', node: 'TacticLearned1_row' },
    { key: 'TacticLearned2', node: 'TacticLearned2_row' },
    { key: 'TacticLearned3', node: 'TacticLearned3_row' },
    { key: 'TacticInspired1', node: 'TacticInspired1_row' },
    { key: 'TacticInspired2', node: 'TacticInspired2_row' },
    { key: 'TacticLocked1', node: 'TacticLocked1_row' },
    { key: 'TacticLocked2', node: 'TacticLocked2_row' },
];

interface DetailSlot {
    name: string;
    state: SkillDetailState;
}

/** 往上找掛有 cc.Canvas 的節點；子視窗掛在它底下才會以 UI 攝影機渲染、蓋在最上層。 */
function canvasNodeOf(start: Node): Node | null {
    let current: Node | null = start;
    while (current) {
        if (current.getComponent('cc.Canvas')) return current;
        current = current.parent;
    }
    return null;
}

function indexByName<T>(items: Iterable<T>, nameOf: (item: T) => string | undefined): Map<string, T> {
    const map = new Map<string, T>();
    for (const item of items) {
        const name = nameOf(item);
        if (name && !map.has(name)) map.set(name, item);
    }
    return map;
}

export class CharacterDs3TacticsChild extends ChildPanelBase {
    override dataSource = 'config';
    private static readonly ROOT_PATH = 'ContentSlot';

    /** 戰法／奧義定義，與技頁共用同一份快取（SkillDefinitionCache） */
    private _tacticsById: Map<string, CanonicalTacticDefinition> = new Map();
    private _tacticsByName: Map<string, CanonicalTacticDefinition> = new Map();
    private _ultimatesById: Map<string, CanonicalUltimateDefinition> = new Map();
    private _ultimatesByName: Map<string, CanonicalUltimateDefinition> = new Map();
    private _slots = new Map<string, DetailSlot>();
    private _boundNodes = new Map<string, { node: Node; handler: () => void }>();
    private _detailWindow: DetailSubWindow | null = null;
    private _ds3Data: GeneralConfig | null = null;

    public override async onMount(_spec: Record<string, unknown>): Promise<void> {
        UCUFLogger.info(LogCategory.LIFECYCLE, '[CharacterDs3TacticsChild] onMount', { rootPath: CharacterDs3TacticsChild.ROOT_PATH });
        this._bindDetailSlots();
        try {
            const [tactics, ultimates] = await Promise.all([loadTacticDefinitionMap(), loadUltimateDefinitionMap()]);
            this._tacticsById = tactics;
            this._tacticsByName = indexByName(tactics.values(), (t) => t.displayName);
            this._ultimatesById = ultimates;
            this._ultimatesByName = indexByName(ultimates.values(), (u) => u.name);
        } catch (error) {
            UCUFLogger.warn(LogCategory.DATA, '[CharacterDs3TacticsChild] 載入戰法定義失敗，詳情子視窗僅顯示名稱', {
                error: error instanceof Error ? error.message : String(error),
            });
        }
    }

    public override onDataUpdate(data: unknown): void {
        if (!data || typeof data !== 'object') {
            return;
        }
        this._ds3Data = data as GeneralConfig;
        const rows = buildDs3TacticRows(this._ds3Data);
        this._rememberSlots(rows);
        TACTIC_DEMO_NODES.forEach((name) => this._setActive(name, false));

        const [primary, ...others] = rows.learned;
        this._setText('TacticMain_glyph', primary?.glyph ?? '—');
        this._setText('TacticMain_name', primary?.name ?? '尚未習得');
        for (let i = 1; i < LEARNED_SLOT_COUNT; i += 1) {
            const row = others[i - 1];
            this._setActive(`TacticLearned${i}_row`, !!row);
            if (!row) continue;
            this._setText(`TacticLearned${i}_glyph`, row.glyph);
            this._setText(`TacticLearned${i}_name`, row.name);
        }

        this._applyLockedRows('TacticInspired', rows.inspired, INSPIRED_SLOT_COUNT);
        this._applyLockedRows('TacticLocked', rows.locked, LOCKED_SLOT_COUNT);
        ds3Reflow(this.hostNode);
    }

    private _applyLockedRows(prefix: string, rows: Ds3LockedTacticRow[], slotCount: number): void {
        this._setActive(`${prefix}_title`, rows.length > 0);
        this._setActive(`${prefix}_grid`, rows.length > 0);
        for (let i = 1; i <= slotCount; i += 1) {
            const row = rows[i - 1];
            this._setActive(`${prefix}${i}_row`, !!row);
            if (!row) continue;
            this._setText(`${prefix}${i}_glyph`, row.glyph);
            this._setText(`${prefix}${i}_name`, row.name);
            this._setText(`${prefix}${i}_lock`, row.hint);
        }
    }

    public override validateDataFormat(data: unknown): string | null {
        if (!data || typeof data !== 'object') {
            return 'CharacterDs3TacticsChild expects a GeneralConfig-like object';
        }
        return null;
    }

    public override onUnmount(): void {
        this._boundNodes.forEach(({ node, handler }) => node.off(Node.EventType.TOUCH_END, handler, this));
        this._boundNodes.clear();
        this._detailWindow?.destroy();
        this._detailWindow = null;
    }

    private _rememberSlots(rows: Ds3TacticRows): void {
        this._slots.clear();
        const [primary, ...others] = rows.learned;
        if (primary) this._slots.set('main', { name: primary.name, state: 'main' });
        others.slice(0, 3).forEach((row, i) => this._slots.set(`TacticLearned${i + 1}`, { name: row.name, state: 'learned' }));
        rows.inspired.forEach((row, i) => this._slots.set(`TacticInspired${i + 1}`, { name: row.name, state: 'inspired' }));
        rows.locked.forEach((row, i) => this._slots.set(`TacticLocked${i + 1}`, { name: row.name, state: 'locked' }));
    }

    private _bindDetailSlots(): void {
        for (const { key, node: nodeName } of DETAIL_SLOT_NODES) {
            if (this._boundNodes.has(key)) continue;
            const node = ds3Node(this.binder, this.hostNode, nodeName);
            if (!node) {
                UCUFLogger.warn(LogCategory.LIFECYCLE, '[CharacterDs3TacticsChild] 找不到可點詳情節點', { nodeName });
                continue;
            }
            const handler = (): void => this._openDetail(key);
            node.on(Node.EventType.TOUCH_END, handler, this);
            this._boundNodes.set(key, { node, handler });
        }
    }

    private _openDetail(key: string): void {
        const slot = this._slots.get(key);
        if (!slot) return;
        const view = buildSkillDetailView(this._sourceOf(slot.name), { state: slot.state });
        const window = this._ensureDetailWindow();
        if (!window) return;
        window.open({ title: view.title, kindLabel: view.kindLabel, body: formatSkillDetailText(view) });
    }

    private _ensureDetailWindow(): DetailSubWindow | null {
        if (this._detailWindow) return this._detailWindow;
        const canvas = canvasNodeOf(this.hostNode);
        if (!canvas) {
            UCUFLogger.warn(LogCategory.LIFECYCLE, '[CharacterDs3TacticsChild] 找不到 Canvas，無法開啟詳情子視窗');
            return null;
        }
        this._detailWindow = new DetailSubWindow(canvas);
        return this._detailWindow;
    }

    /** 依名稱（或 id）從戰法庫／奧義庫取資料；效果數值走同一份 BattleSkillProfile。查無定義時只有名稱。 */
    private _sourceOf(name: string): SkillDetailSource {
        const tactic = this._tacticsById.get(name) ?? this._tacticsByName.get(name);
        if (tactic) {
            const profile = tactic.battleSkillId ? resolveBattleSkillProfile(tactic.battleSkillId) : null;
            return {
                kind: 'tactic',
                name: tactic.displayName,
                category: tactic.category ? formatTacticCategory(tactic.category) : null,
                tpCost: getTacticTpCost(tactic.id),
                effectKind: profile?.effectKind ?? null,
                coefficient: profile?.coefficient ?? null,
                scalingStat: profile?.scalingStat ?? null,
                targetMode: profile?.targetMode ?? tactic.targetMode ?? null,
                timing: tactic.timing ?? null,
                maxTargets: profile?.maxTargets ?? null,
                pendingEffect: profile?.pendingEffect ?? null,
            };
        }
        const ultimate = this._ultimatesById.get(name) ?? this._ultimatesByName.get(name);
        if (ultimate) {
            const profile = ultimate.battleSkillId ? resolveBattleSkillProfile(ultimate.battleSkillId) : null;
            return {
                kind: 'ultimate',
                name: ultimate.name,
                description: ultimate.description ?? null,
                vitalityCostPct: ultimate.vitalityCostPct ?? null,
                unlockReincarnation: ultimate.unlockReincarnation ?? null,
                effectKind: profile?.effectKind ?? null,
                coefficient: profile?.coefficient ?? null,
                scalingStat: profile?.scalingStat ?? null,
                targetMode: profile?.targetMode ?? ultimate.targetMode ?? null,
                timing: ultimate.timing ?? null,
                maxTargets: profile?.maxTargets ?? null,
                pendingEffect: profile?.pendingEffect ?? null,
            };
        }
        return { kind: 'tactic', name };
    }

    private _setText(nodeName: string, text: string): void {
        const label = ds3Label(this.binder, this.hostNode, nodeName);
        if (label) label.string = text;
    }

    private _setActive(nodeName: string, active: boolean): void {
        ds3SetActive(this.binder, this.hostNode, nodeName, active);
    }
}
